import { useEffect, useState } from "react";
import i18n, { languages, languageType } from "../i18n";



export default function LanguageSelector() {
    const [language, setLanguage] = useState<languageType>("en");

    useEffect(() => {
        changeLanguage(getDefaultLanguage());
    }, []);

    const changeLanguage = (lng: string) => {
        i18n.changeLanguage(lng);
        setLanguage(lng as languageType);
        localStorage.setItem('language', lng);
    };

    return <select value={language} onChange={(e) => changeLanguage(e.target.value as languageType)} className="p-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500">
        {languages.map((language) => <option key={language.code} value={language.code}>{language.logo} {language.name}</option>)}
    </select>
}

function getDefaultLanguage(): languageType {
    const storedLanguage = localStorage.getItem('language');
    let result: languageType;
    if (storedLanguage) {
        result = storedLanguage as languageType;
    } else {
        const browserLanguage = navigator.language.split('-')[0];
        const availableLanguages = ['en', 'zh']; // 假设支持的语言
        console.log(`browserLanguage: ${browserLanguage}`);
        result = availableLanguages.includes(browserLanguage) ? browserLanguage as languageType : 'en';
    }
    return result;
}