import React from 'react';
import { Note } from '../types';
import { useTranslation } from 'react-i18next';
import ReactMarkdown from 'react-markdown';
import { formatDateTime, formatRelativeTime } from '../utils/dateFormat';
import AddNote from './AddNote';
import { Pagination } from './Pagination';
import { Action, dispatchThenReload, State } from '../store';
import { useDispatch, useSelector } from 'react-redux';
import EditableNote from './EditableNote';
import { produce } from 'immer';
import { DatabaseService } from '../services/db';
import { ThunkDispatch } from 'redux-thunk';
import { UnknownAction } from '@reduxjs/toolkit';

interface NotesPanelProps {}

export const NotesPanel: React.FC<NotesPanelProps> = () => {
  const { t } = useTranslation();
  const editingNote = useSelector((state: State) => state.editingNote);
  const pagination = useSelector((state: State) => state.pagination);
  const notes = useSelector((state: State) => state.notes);

  const dispatch: ThunkDispatch<State, void, UnknownAction> = useDispatch();

  const handleDeleteNote = async (note: Note) => {
    await DatabaseService.markNoteAsDeleted(note);
    dispatch(Action.loadLocalNotesThunk(pagination)) ;
  }
  const handleEditNote = async (note: Note) => {
    dispatch(Action.setEditingNote(note))
  }
  const handleCancelEdit = () => {
    dispatch(Action.setEditingNote(null))
  };
  const handleSaveNote = async (content: string) => {
    if(editingNote == null) {
      console.error("unexpected: editingNote is null")
      return
    }

    const updatedNote: Note = produce(editingNote, (draft) => {
      draft.content = content
    })

    await DatabaseService.saveNote(updatedNote);
    dispatch(dispatchThenReload(() => {
      dispatch(Action.setEditingNote(null));
    }))

    // TODO: the sync logic is everywhere. Group them together.
    dispatch(Action.syncNotesThunk());
  };

  const { currentPage, pageSize, total } = pagination;
  
  const handlePageChange = (page: number) => {
    dispatch(dispatchThenReload((dispatch) => {
      dispatch(Action.setPage(page));
    }));
  };

  const handlePageSizeChange = (size: number) => {
    dispatch(dispatchThenReload((dispatch) => {
      dispatch(Action.setPageSize(size));
    }));
  };

  return (
    <div className="notes-panel">
      <div className="notes-container">
        <div className="flex justify-between items-center">
          <h1 className='site-title'>{t('title.my_notes')}</h1>
        </div>
        <AddNote/>

        {notes.map(note => (
          <article key={note.uuid} className="note-article">
            <header className="note-header">
              <h1 className="note-title">{formatDateTime(note.created_at)}</h1>
              <div className="note-meta flex justify-between items-center">
                <span>{t("note.updated_at", {time: formatRelativeTime(note.updated_at, t)})}</span>
                {note.created_at !== note.updated_at && 
                  <span>{t("note.created_at", {time: formatRelativeTime(note.created_at, t)})}</span>
                }
              </div>
            </header>

            {editingNote?.uuid === note.uuid ? (
              <EditableNote
                initialContent={editingNote.content}
                onSave={handleSaveNote}
                onCancel={handleCancelEdit}
              />
            ) : (
              <div className="note-content-container">
                <section className="note-markdown-content">
                  <ReactMarkdown>{note.content}</ReactMarkdown>
                </section>
                <button 
                  onClick={() => handleEditNote(note)} 
                  className="action-primary-button"
                >
                  {t('action.edit')}
                </button>
                <button 
                  onClick={() => handleDeleteNote(note)} 
                  className="action-danger-button ml-2"
                >
                  {t('action.delete')}
                </button>
              </div>
            )}
          </article>
        ))}

        <Pagination
          currentPage={currentPage}
          pageSize={pageSize}
          total={total}
          onPageChange={handlePageChange}
          onPageSizeChange={handlePageSizeChange}
        />
      </div>
    </div>
  );
};