import React, { useState, useEffect } from 'react';
import { DateRange, SortField, SortOption } from '../types/index';
import { useTranslation } from 'react-i18next';
import { useDispatch, useSelector } from 'react-redux';
import { Action, dispatchThenReload, State } from '../store';
import { ThunkDispatch } from 'redux-thunk';
import { UnknownAction } from '@reduxjs/toolkit';
import LanguageSelector from './LanguageSelector';

interface ToolbarProps {
  onSync: () => void;
}

export function Toolbar({ 
  onSync, 
}: ToolbarProps) {
  const { sortOption, dateRange} = useSelector((state: State) => state.pagination);
  const isSyncing = useSelector((state: State) => state.isSyncing);
  const username = useSelector((state: State) => state.username);
  const addingNote = useSelector((state: State) => state.addingNote);

  const dispatch: ThunkDispatch<State, void, UnknownAction>   = useDispatch();
  const { t } = useTranslation();
  const [isVisible, setIsVisible] = useState(true);
  const [lastScrollTop, setLastScrollTop] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      const currentScrollTop = window.pageYOffset || document.documentElement.scrollTop;
      if (currentScrollTop > lastScrollTop) {
        setIsVisible(false); // 向下滚动，隐藏工具栏
      } else {
        setIsVisible(true); // 向上滚动，显示工具栏
      }
      setLastScrollTop(currentScrollTop <= 0 ? 0 : currentScrollTop);
    };

    window.addEventListener('scroll', handleScroll);
    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, [lastScrollTop]);

  const handleSortChange = async (newSortOption: SortOption) => {
    dispatch(dispatchThenReload(() => {
      dispatch(Action.setSortOption(newSortOption));
    }))
  };

  const handleDateRangeChange = async(newRange: DateRange) => {
    dispatch(dispatchThenReload((d, getState) => {
      d(Action.setDateRange(newRange));
    }))
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    dispatch(Action.logout());
  };

  const onAddNoteClicked = async () => {
    dispatch(Action.setAddingNoteState(true));
  }

  return (
    <div className={`toolbar ${isVisible ? 'visible' : 'hidden'}`}>
      {username ? (
        <>
          <div className="flex flex-col md:flex-row w-full gap-2 p-2">
            {/* 日期选择器组 */}
            <div className="flex flex-wrap items-center gap-2 min-w-0 w-full md:w-auto">
              <input
                type="date"
                value={dateRange.startDate}
                max={dateRange.endDate}
                onChange={(e) => handleDateRangeChange({
                  ...dateRange,
                  startDate: e.target.value
                })}
                className="p-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500 flex-1 min-w-0"
              />
              <span className="whitespace-nowrap">{t('to')}</span>
              <input
                type="date"
                value={dateRange.endDate}
                min={dateRange.startDate}
                onChange={(e) => handleDateRangeChange({
                  ...dateRange,
                  endDate: e.target.value
                })}
                className="p-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500 flex-1 min-w-0"
              />
            </div>

            {/* 排序控制组 */}
            <div className="flex items-center gap-2 min-w-0 w-full md:w-auto">
              <select
                value={sortOption.field}
                onChange={(e) => handleSortChange({
                  ...sortOption,
                  field: e.target.value as SortField
                })}
                className="p-2 border border-gray-300 rounded focus:outline-none focus:border-blue-500 flex-1 min-w-0"
              >
                <option value="created_at">{t('creation_time')}</option>
                <option value="updated_at">{t('modification_time')}</option>
              </select>
              <button
                className={`p-2 border border-gray-300 rounded bg-white hover:bg-gray-100 transition ${sortOption.direction}`}
                onClick={() => handleSortChange({
                  ...sortOption,
                  direction: sortOption.direction === 'desc' ? 'asc' : 'desc'
                })}
              >
                {sortOption.direction === 'desc' ? '↓' : '↑'}
              </button>
            </div>

            {/* 控制按钮组 */}
            <div className="flex flex-wrap items-center gap-2 min-w-0 w-full md:w-auto md:ml-auto">
              <button onClick={onAddNoteClicked} className="action-primary-button whitespace-nowrap">
                {t('action.add_note')}
              </button>
              <button 
                onClick={onSync} 
                disabled={isSyncing}
                className="p-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition whitespace-nowrap"
              >
                {isSyncing ? t('sync.syncing') : t('sync.sync_notes')}
              </button>
              <button onClick={handleLogout} className="whitespace-nowrap action-secondary-button">{t('action.logout')}</button>
              <LanguageSelector/>
            </div>
          </div>
        </>
      ) : (
        <div className="flex items-center gap-2 p-2 w-full justify-end">
          <LanguageSelector/>
        </div>
      )}
    </div>
  );
} 
