import React, { useState } from 'react';
import { ApiService } from '../services/api';
import { useTranslation } from 'react-i18next';
import { useDispatch } from 'react-redux';
import { Action, State, Toast } from '../store';
import { ThunkDispatch } from 'redux-thunk';
import { UnknownAction } from '@reduxjs/toolkit';

const Login: React.FC<{successCallback: ()=>void }> = ({successCallback}) => {
  const dispatch: ThunkDispatch<State, void, UnknownAction> = useDispatch();
  const { t } = useTranslation();

  // 使用本地状态来管理用户名和密码
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const response = await ApiService.login({ username, password });
      if (response.error) {
        throw(response.error);
      }
      localStorage.setItem('token', response.token);
      dispatch(Action.login(username));
      const toast: Toast = { id: Date.now(), message: t('login.succeeded'), color: "green" };
      dispatch(Action.showToastThunk({toast}));

      successCallback();
    } catch (error) {
      console.error('登录失败:', error);
      const toast: Toast = { id: Date.now(), message: t('login.failed'), color: "red" };
      dispatch(Action.showToastThunk({toast}));
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen p-5 bg-gray-100">
      <div className="bg-white p-8 rounded-lg shadow-md w-full max-w-md">
        <h2 className="text-center text-gray-800 text-2xl mb-5">{t('title.login')}</h2>
        <form className="flex flex-col gap-4" onSubmit={handleLogin}>
          <input
            type="text"
            placeholder={t('login.username')}
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
            className="p-3 border border-gray-300 rounded focus:outline-none focus:border-blue-500"
          />
          <input
            type="password"
            placeholder={t('login.password')}
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            className="p-3 border border-gray-300 rounded focus:outline-none focus:border-blue-500"
          />
          <button
            type="submit"
            className="p-3 bg-blue-500 text-white rounded hover:bg-blue-600 transition"
          >
            {t('action.login')}
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login;
