import React, { useEffect, useRef, useState } from 'react';
import { DatabaseService } from './services/db';
import { Toolbar } from './components/Toolbar';
import './styles/index.css';
import ToastBox from './components/ToastBox';
import Login from './components/Login';
import PullToRefresh from './components/PullToRefresh';
import { NotesPanel } from './components/NotesPanel';
import { ResolutionsPanel } from './components/ResolutionsPanel';
import { Action } from './store';
import { useDispatch, useSelector } from 'react-redux';
import { State } from './store';
import { ThunkDispatch } from 'redux-thunk';
import { UnknownAction } from '@reduxjs/toolkit';


function parseJwt(token: string) {
  try {
    const base64Url = token.split('.')[1];
    const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
    const jsonPayload = decodeURIComponent(atob(base64).split('').map(function(c) {
      return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));

    return JSON.parse(jsonPayload);
  } catch (error) {
    console.error('Failed to parse JWT:', error);
    return null;
  }
}

const VERSION = '250202-hide-toolbar-when-scroll-down';
console.log('VERSION', VERSION);

function App() {
  const pagination = useSelector((state: State) => state.pagination);
  const username = useSelector((state: State) => state.username);

  const dispatch: ThunkDispatch<State, void, UnknownAction> = useDispatch();

  useEffect(() => {
    if(username) {
      return
    }

    const token = localStorage.getItem('token');
    if (token) {
      const decodedToken = parseJwt(token);
      const username = decodedToken ? decodedToken.username : null;
      dispatch(Action.login(username));
      initializeApp();
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      // TODO: make this configurable
      if ((event.metaKey || event.ctrlKey) && event.key === ';') {
        event.preventDefault();
        dispatch(Action.setAddingNoteState(true));
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [dispatch]);

  const initializeApp = async () => {
    await DatabaseService.init();
    dispatch(Action.loadLocalNotesThunk(pagination));
  };

  const handleSync = async () => {
    dispatch(Action.syncNotesThunk());
  };

  useEffect(() => {
    const checkAndSync = async () => {
      const lastSync = await DatabaseService.getLastSync();
      const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);

      if (!lastSync || new Date(lastSync.timestamp) < oneHourAgo) {
        await handleSync();
      }
    };

    checkAndSync();
  }, []);

  return (
    <div>
      <Toolbar 
        onSync={handleSync}
      />

      <ToastBox />

      {!username ? (
        <Login successCallback={async () => {
          await initializeApp();
        }} />
      ) : (
        <PullToRefresh onRefresh={handleSync}>
          <div className="flex">
            <ResolutionsPanel />
            <NotesPanel />
          </div>
        </PullToRefresh>
      )}
    </div>
  );
}

export default App;
